/**
 * Jinx Bounty Hunter + Philosopher: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Bounty_Hunter
 * Wiki: https://wiki.bloodontheclocktower.com/Philosopher
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes/jinxes.ts';
import { gainedPartnerJinx } from '#lib/core/rules/jinxes/jinx-effects.ts';
import { nightStepAlerts } from '#lib/core/rules/night/night-alerts.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Bounty Hunter + Philosopher jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'bountyhunter', 'philosopher');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('bountyhunter')?.name).toBe('Bounty Hunter');
		expect(data.byId.get('philosopher')?.name).toBe('Philosopher');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['bountyhunter', 'philosopher'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['bountyhunter'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['philosopher'])).not.toContain(jinx);
	});

	describe('a Philosopher who gains the Bounty Hunter ability may turn a Townsfolk evil', () => {
		const ids = ['philosopher', 'bountyhunter', 'chef', 'empath', 'imp'];
		const script = scriptOf(ids);
		// The Philosopher chose the Bounty Hunter: their token swapped, Is The Philosopher on them.
		const gained = scenario(['bountyhunter', 'chef', 'empath', 'imp'], { script }).reminder(
			0,
			'philosopher',
			'Is The Philosopher'
		);
		const alerts = (s: Scenario) =>
			nightStepAlerts(s.game, 'bountyhunter', s.characters).filter(
				(a) => a.kind === 'partner-setup'
			);

		it("is data in the Philosopher's rules", () => {
			// Wiki: "If the Philosopher gains the Bounty Hunter ability, a Townsfolk might turn evil."
			expect(ownJinxRules(gained.game, 'philosopher', 'bountyhunter', gained.characters)).toEqual({
				partnerSetup: {}
			});
			expect(gainedPartnerJinx(gained.game, gained.seat(0), gained.characters)).toMatchObject({
				owner: 'philosopher',
				partner: 'bountyhunter'
			});
		});

		it('says at the Bounty Hunter step that its setup change may be made now', () => {
			// Wiki: "a Townsfolk might turn evil."
			expect(alerts(gained)).toMatchObject([
				{ seatId: gained.seat(0), source: { characterId: 'philosopher' }, partner: 'bountyhunter' }
			]);
		});

		it('says nothing for the real Bounty Hunter', () => {
			// Wiki: "If the Philosopher gains the Bounty Hunter ability"
			const s = scenario(['bountyhunter', 'chef', 'empath', 'imp'], { script });
			expect(alerts(s)).toEqual([]);
		});
	});
});
